fn fri05_c05_grid_positive_margin_bounds(output: NodeOutput) -> (Point<f32>, Point<f32>) {
    let minimum = Point::new(
        output.location.x - output.margin.left.max(0.0),
        output.location.y - output.margin.top.max(0.0),
    );
    let maximum = Point::new(
        output.location.x + output.size.width + output.margin.right.max(0.0),
        output.location.y + output.size.height + output.margin.bottom.max(0.0),
    );
    (minimum, maximum)
}

#[test]
fn fri05_c05_grid_contribution_container_origins_margins_terminal_padding_and_absolute_are_exact() {
    let padding = Edges::new(
        Length::px(7.0),
        Length::px(4.0),
        Length::px(3.0),
        Length::px(10.0),
    );
    let mut tree = OracleTree::new()
        .children(0, [1, 2, 3])
        .children(1, [])
        .children(2, [])
        .children(3, [])
        .style(
            0,
            NodeInput {
                display: Display::Grid,
                size: Size::ZERO.map(PreferredSize::px),
                padding,
                grid_template_columns: vec![TrackComponent::px(0.0)],
                grid_template_rows: vec![TrackComponent::px(0.0)],
                ..NodeInput::default()
            },
        )
        .style(
            1,
            NodeInput {
                display: Display::Block,
                size: Size::new(PreferredSize::px(5.0), PreferredSize::px(6.0)),
                justify_self: Some(AlignItems::Start),
                align_self: Some(AlignItems::Start),
                margin: Edges::new(
                    LengthAuto::px(2.0),
                    LengthAuto::px(4.0),
                    LengthAuto::px(3.0),
                    LengthAuto::px(1.0),
                ),
                ..NodeInput::default()
            },
        )
        .style(
            2,
            NodeInput {
                display: Display::Block,
                position: Position::Relative,
                size: Size::new(PreferredSize::px(3.0), PreferredSize::px(4.0)),
                justify_self: Some(AlignItems::Start),
                align_self: Some(AlignItems::Start),
                inset: Edges::new(
                    LengthAuto::px(-12.0),
                    LengthAuto::AUTO,
                    LengthAuto::AUTO,
                    LengthAuto::px(-15.0),
                ),
                margin: Edges::all(LengthAuto::px(-8.0)),
                ..NodeInput::default()
            },
        )
        .style(
            3,
            NodeInput {
                display: Display::Block,
                position: Position::Absolute,
                size: Size::new(PreferredSize::px(5.0), PreferredSize::px(5.0)),
                inset: Edges::new(
                    LengthAuto::px(2.0),
                    LengthAuto::AUTO,
                    LengthAuto::AUTO,
                    LengthAuto::px(30.0),
                ),
                margin: Edges {
                    right: LengthAuto::px(7.0),
                    ..Edges::all(LengthAuto::ZERO)
                },
                ..NodeInput::default()
            },
        );

    let output = compute_grid(
        &mut tree,
        0,
        fri05_c05_grid_sizing_input(Size::splat(Some(0.0))),
    )
    .expect("grid origin and contribution case computes");
    let first = tree.layout(1).expect("first in-flow output");
    let second = tree.layout(2).expect("second in-flow output");
    let absolute = tree.layout(3).expect("absolute output");
    assert_eq!(first.source_index, SourceIndex::new(0));
    assert_eq!(second.source_index, SourceIndex::new(1));
    assert_eq!(absolute.source_index, SourceIndex::new(2));

    let bounds = [first, second, absolute].map(fri05_c05_grid_positive_margin_bounds);
    let minimum = bounds
        .iter()
        .fold(Point::<f32>::ZERO, |minimum, (origin, _)| {
            Point::new(minimum.x.min(origin.x), minimum.y.min(origin.y))
        });
    let mut maximum = bounds.iter().fold(Point::<f32>::ZERO, |maximum, (_, end)| {
        Point::new(maximum.x.max(end.x), maximum.y.max(end.y))
    });
    let in_flow_end = [first, second]
        .map(fri05_c05_grid_positive_margin_bounds)
        .iter()
        .fold(Point::<f32>::ZERO, |maximum, (_, end)| {
            Point::new(maximum.x.max(end.x), maximum.y.max(end.y))
        });
    maximum.x = maximum.x.max(in_flow_end.x + 4.0);
    maximum.y = maximum.y.max(in_flow_end.y + 3.0);

    assert!(first.location.x > 0.0 && first.location.y > 0.0);
    assert!(second.location.x < 0.0 && second.location.y < 0.0);
    assert_eq!(
        output.content_size,
        Size::new(maximum.x - minimum.x, maximum.y - minimum.y),
        "container-local locations, positive outsets, negative starts, terminal padding, and the current absolute child contribute without area-relative subtraction"
    );
}

#[test]
fn fri05_c05_grid_contribution_zero_axis_visible_descendants_and_traps_are_independent() {
    for display in [Display::Grid, Display::GridLanes] {
        for (overflow, child_size, expected) in [
            (
                computed_overflow(Overflow::Visible, Overflow::Clip),
                Size::new(0.0, 5.0),
                Size::new(20.0, 0.0),
            ),
            (
                computed_overflow(Overflow::Clip, Overflow::Visible),
                Size::new(5.0, 0.0),
                Size::new(0.0, 30.0),
            ),
            (
                computed_overflow(Overflow::Hidden, Overflow::Scroll),
                Size::new(0.0, 5.0),
                Size::ZERO,
            ),
            (
                computed_overflow(Overflow::Auto, Overflow::Auto),
                Size::new(5.0, 0.0),
                Size::ZERO,
            ),
        ] {
            let output = fri05_c05_grid_contribution_nested(display, overflow, child_size);
            let expected = if display == Display::GridLanes && child_size.width == 0.0 {
                expected.max(Size::new(0.0, child_size.height))
            } else {
                expected
            };
            assert_eq!(output.content_size, expected, "{display:?} {overflow:?}");
        }
    }
}

#[test]
fn fri05_c05_grid_auto_minimum_computed_scrollability_reaches_grid_and_lanes_front_doors() {
    for display in [Display::Grid, Display::GridLanes] {
        for writing_mode in [
            WritingMode::HorizontalTb,
            WritingMode::VerticalRl,
            WritingMode::VerticalLr,
            WritingMode::SidewaysRl,
            WritingMode::SidewaysLr,
        ] {
            for direction in [Direction::Ltr, Direction::Rtl] {
                let auto_flows: &[GridAutoFlow] = if display == Display::GridLanes {
                    &[GridAutoFlow::Row, GridAutoFlow::Column]
                } else {
                    &[GridAutoFlow::Row]
                };
                for &grid_auto_flow in auto_flows {
                    for overflow in [
                        Overflow::Visible,
                        Overflow::Clip,
                        Overflow::Hidden,
                        Overflow::Scroll,
                        Overflow::Auto,
                    ] {
                        let mut tree = fri05_c05_grid_sizing_tree(
                            display,
                            writing_mode,
                            direction,
                            computed_overflow(overflow, overflow),
                            false,
                            Size::new(PreferredSize::AUTO, PreferredSize::AUTO),
                            grid_auto_flow,
                        );

                        compute_grid(
                            &mut tree,
                            0,
                            fri05_c05_grid_sizing_input(Size::splat(Some(40.0))),
                        )
                        .expect("grid automatic-minimum case computes");

                        let layout_input = tree
                            .inputs(1)
                            .iter()
                            .find(|input| input.run_mode() == RunMode::PerformLayout)
                            .expect("grid item receives final layout input");
                        let item_size = Size::new(Some(20.0), Some(30.0));
                        let content_size = Size::new(Some(80.0), Some(90.0));
                        let zero = Size::new(Some(0.0), Some(0.0));
                        let expected_known = if display == Display::Grid {
                            match overflow {
                                Overflow::Visible => content_size,
                                Overflow::Clip => item_size,
                                Overflow::Hidden | Overflow::Scroll | Overflow::Auto => zero,
                            }
                        } else {
                            let flow_axes = FlowAxes::new(writing_mode, direction);
                            let grid_axis = grid_axis_for_lanes(grid_auto_flow);
                            let physical_axis = match grid_axis.logical_axis() {
                                LogicalAxis::Inline => flow_axes.inline_axis(),
                                LogicalAxis::Block => flow_axes.block_axis(),
                            };
                            let selected = match (physical_axis, overflow) {
                                (PhysicalAxis::Horizontal, Overflow::Visible) => content_size.width,
                                (PhysicalAxis::Vertical, Overflow::Visible) => content_size.height,
                                (PhysicalAxis::Horizontal, Overflow::Clip) => item_size.width,
                                (PhysicalAxis::Vertical, Overflow::Clip) => item_size.height,
                                (_, Overflow::Hidden | Overflow::Scroll | Overflow::Auto) => {
                                    Some(0.0)
                                }
                            };
                            match physical_axis {
                                PhysicalAxis::Horizontal => Size::new(selected, item_size.height),
                                PhysicalAxis::Vertical => Size::new(item_size.width, selected),
                            }
                        };
                        assert_eq!(
                            layout_input.known(),
                            expected_known,
                            "{display:?} {writing_mode:?} {direction:?} {grid_auto_flow:?} {overflow:?} automatic minimum"
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn fri05_c05_grid_intrinsic_overflow_projects_used_axes_and_traps_descendants() {
    let writing_modes = [
        WritingMode::HorizontalTb,
        WritingMode::VerticalRl,
        WritingMode::VerticalLr,
        WritingMode::SidewaysRl,
        WritingMode::SidewaysLr,
    ];
    for display in [Display::Grid, Display::GridLanes] {
        for writing_mode in writing_modes {
            for direction in [Direction::Ltr, Direction::Rtl] {
                for (overflow, replaced, expected) in [
                    (
                        computed_overflow(Overflow::Visible, Overflow::Visible),
                        false,
                        Size::new(80.0, 90.0),
                    ),
                    (
                        computed_overflow(Overflow::Clip, Overflow::Clip),
                        false,
                        Size::new(20.0, 30.0),
                    ),
                    (
                        computed_overflow(Overflow::Hidden, Overflow::Hidden),
                        false,
                        Size::new(20.0, 30.0),
                    ),
                    (
                        computed_overflow(Overflow::Hidden, Overflow::Hidden),
                        true,
                        Size::new(20.0, 30.0),
                    ),
                    (
                        computed_overflow(Overflow::Scroll, Overflow::Scroll),
                        false,
                        Size::new(20.0, 30.0),
                    ),
                    (
                        computed_overflow(Overflow::Auto, Overflow::Auto),
                        false,
                        Size::new(20.0, 30.0),
                    ),
                    (
                        computed_overflow(Overflow::Visible, Overflow::Clip),
                        false,
                        Size::new(80.0, 30.0),
                    ),
                    (
                        computed_overflow(Overflow::Clip, Overflow::Visible),
                        false,
                        Size::new(20.0, 90.0),
                    ),
                ] {
                    let mut tree = fri05_c05_grid_sizing_tree(
                        display,
                        writing_mode,
                        direction,
                        overflow,
                        replaced,
                        Size::new(PreferredSize::px(20.0), PreferredSize::px(30.0)),
                        GridAutoFlow::Row,
                    );

                    let output =
                        compute_grid(&mut tree, 0, fri05_c05_grid_sizing_input(Size::NONE))
                            .expect("grid intrinsic overflow case computes");

                    assert_eq!(
                        output.size, expected,
                        "{display:?} {writing_mode:?} {direction:?} {overflow:?} replaced={replaced}"
                    );
                }
            }
        }
    }
}

