#[test]
fn grid_lanes_order_modified_sequence_drives_running_offsets_and_intrinsic_contributions_in_both_scalar_lanes()
 {
    assert_grid_lanes_order_modified_sequence::<f32>();
    assert_grid_lanes_order_modified_sequence::<f64>();
}

fn assert_grid_lanes_order_modified_sequence<S: LayoutScalar>()
where
    OracleTreeOf<S>: Compute + Traverse<Node = u32, Scalar = S>,
{
    let item_style = |order, width, height| NodeInputOf::<S> {
        item_order: ItemOrder::new(order),
        size: Size::new(
            PreferredSizeOf::px(S::from_f64(width)),
            PreferredSizeOf::px(S::from_f64(height)),
        ),
        grid_column: GridPlacement::try_line(1).expect("one is a valid grid line"),
        ..NodeInputOf::default()
    };
    let mut tree = OracleTreeOf::<S>::new()
        .children(0, [1, 2, 3, 4, 5, 6])
        .children(1, [])
        .children(2, [])
        .children(3, [])
        .children(4, [])
        .children(5, [])
        .children(6, [])
        .style(
            0,
            NodeInputOf {
                display: Display::GridLanes,
                grid_template_columns: vec![TrackComponentOf::AUTO, TrackComponentOf::AUTO],
                grid_template_rows: vec![TrackComponentOf::px(S::ZERO)],
                grid_flow_tolerance: GridFlowToleranceOf::Length(LengthOf::ZERO),
                ..NodeInputOf::default()
            },
        )
        .style(
            1,
            NodeInputOf {
                grid_column: GridPlacement::try_line_span(1, 2)
                    .expect("line one with span two is valid"),
                ..item_style(2, 100.0, 10.0)
            },
        )
        .style(
            2,
            NodeInputOf {
                display: Display::None,
                item_order: ItemOrder::new(i32::MIN),
                ..item_style(0, 500.0, 500.0)
            },
        )
        .style(3, item_style(-1, 80.0, 20.0))
        .style(
            4,
            NodeInputOf {
                position: Position::Absolute,
                item_order: ItemOrder::new(i32::MIN),
                ..item_style(0, 500.0, 500.0)
            },
        )
        .style(5, item_style(0, 0.0, 30.0))
        .style(6, item_style(2, 0.0, 40.0));

    let placement = |column, in_flow| ResolvedGridItemPlacement {
        column,
        row: GridPlacement::try_line(1).expect("one is a valid grid line"),
        absolute_column: column,
        absolute_row: GridPlacement::try_line(1).expect("one is a valid grid line"),
        in_flow,
    };
    let placements = GridPlacementContext::new(
        vec![1, 2, 3, 4, 5, 6],
        vec![
            placement(
                GridPlacement::try_line_span(1, 2).expect("line-span placement is valid"),
                true,
            ),
            placement(GridPlacement::AUTO, false),
            placement(
                GridPlacement::try_line(1).expect("one is a valid grid line"),
                true,
            ),
            placement(GridPlacement::AUTO, false),
            placement(
                GridPlacement::try_line(1).expect("one is a valid grid line"),
                true,
            ),
            placement(
                GridPlacement::try_line(1).expect("one is a valid grid line"),
                true,
            ),
        ],
    )
    .with_order_modified_indexes(vec![
        SourceIndex::new(2),
        SourceIndex::new(4),
        SourceIndex::new(0),
        SourceIndex::new(5),
    ]);
    let constants = Constants {
        flow_axes: FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
        explicit_definite_content_size: Size::NONE,
        node_outer_size: Size::NONE,
        node_inner_size: Size::NONE,
        node_min_size: Size::NONE,
        node_max_size: Size::NONE,
        available_inner_size: Size::NONE,
        content_box_inset: Edges::ZERO,
        padding: Edges::ZERO,
        border: Edges::ZERO,
    };
    let tracks = [TrackSizingOf::AUTO, TrackSizingOf::AUTO];
    let intrinsic_sizes = lane_intrinsic_track_sizes(
        &mut tree,
        0,
        LaneIntrinsicTrackSizeInput {
            constants: &constants,
            axis: GridAxisKind::Column,
            tracks: &tracks,
            gap: S::ZERO,
            available: AvailableOf::MAX_CONTENT,
            available_basis: None,
            lines: GridLines {
                column_explicit_start: 0,
                column_explicit_count: 2,
                row_explicit_start: 0,
                row_explicit_count: 1,
            },
            placements: &placements,
        },
    )
    .expect("intrinsic collection succeeds")
    .expect("intrinsic placement is valid");
    assert_eq!(
        intrinsic_sizes,
        vec![S::from_f64(90.0), S::from_f64(10.0)],
        "overlapping definite spans apply in the order-modified sequence"
    );

    let output = compute_grid(
        &mut tree,
        0,
        ComputeInputOf::for_child(
            RunMode::PerformLayout,
            SizingMode::InherentSize,
            RequestedAxis::Both,
            Size::NONE,
            Size::NONE,
            ContainingLayoutContext::new(
                FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
                ParentFormattingContext::NoParent,
            ),
            Size::new(AvailableOf::MAX_CONTENT, AvailableOf::MAX_CONTENT),
        ),
    )
    .expect("order-modified grid-lanes layout succeeds");

    assert_eq!(output.size.width, S::from_f64(140.0));
    for (node, expected_y) in [(3, 0.0), (5, 20.0), (1, 50.0), (6, 60.0)] {
        let layout = tree.layout(node).expect("in-flow lane child is staged");
        assert_eq!(layout.source_index, SourceIndex::new((node - 1) as usize));
        assert_eq!(layout.location.y, S::from_f64(expected_y));
    }
    assert_eq!(
        Traverse::children(&tree, 0).collect::<Vec<_>>(),
        [1, 2, 3, 4, 5, 6],
        "final traversal stays in source order"
    );
    assert!(tree.inputs(2).iter().any(|input| {
        input.run_mode() == RunMode::PerformHiddenLayout
            && input.parent_formatting_context() == ParentFormattingContext::Grid
    }));
    assert_eq!(
        tree.layout(4)
            .expect("absolute lane child is staged")
            .source_index,
        SourceIndex::new(3)
    );
}

#[test]
fn grid_lanes_replaced_normal_preplacement_starts_while_explicit_stretch_remains_in_both_scalar_lanes()
 {
    assert_grid_lanes_replaced_normal_preplacement::<f32>();
    assert_grid_lanes_replaced_normal_preplacement::<f64>();
}

fn assert_grid_lanes_replaced_normal_preplacement<S: LayoutScalar>()
where
    OracleTreeOf<S>: Compute + Traverse<Node = u32, Scalar = S>,
{
    for grid_axis in [GridAxisKind::Column, GridAxisKind::Row] {
        for (label, replaced, item_alignment, container_alignment, stretches) in [
            ("replaced normal", true, None, None, false),
            ("non-replaced normal", false, None, None, true),
            (
                "explicit item stretch",
                true,
                Some(AlignItems::Stretch),
                None,
                true,
            ),
            (
                "explicit container stretch",
                true,
                None,
                Some(AlignItems::Stretch),
                true,
            ),
        ] {
            let grid_axis_size = match grid_axis {
                GridAxisKind::Column => S::from_f64(100.0),
                GridAxisKind::Row => S::from_f64(80.0),
            };
            let measured =
                ComputeOutputOf::from_outer_size(Size::new(S::from_f64(30.0), S::from_f64(20.0)));
            let container_style = NodeInputOf {
                justify_items: container_alignment,
                align_items: container_alignment,
                ..NodeInputOf::default()
            };
            let child_style = NodeInputOf {
                item_is_replaced: replaced,
                justify_self: item_alignment,
                align_self: item_alignment,
                ..NodeInputOf::default()
            };
            let mut tree = OracleTreeOf::<S>::new()
                .children(1, [])
                .style(1, child_style.clone())
                .measure(1, measured);
            let constants = Constants {
                flow_axes: FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
                explicit_definite_content_size: Size::NONE,
                node_outer_size: Size::NONE,
                node_inner_size: Size::NONE,
                node_min_size: Size::NONE,
                node_max_size: Size::NONE,
                available_inner_size: Size::NONE,
                content_box_inset: Edges::ZERO,
                padding: Edges::ZERO,
                border: Edges::ZERO,
            };
            measure_lane_axis_margin_box_with_grid_axis(
                &mut tree,
                1,
                LaneAxisMarginBoxMeasureInput {
                    child_style: &child_style,
                    container_style: &container_style,
                    constants: &constants,
                    lane_axis: match grid_axis {
                        GridAxisKind::Column => GridAxisKind::Row,
                        GridAxisKind::Row => GridAxisKind::Column,
                    },
                    containing_block: GridLanesItemContainingBlockOf::new(
                        constants.flow_axes,
                        grid_axis,
                        grid_axis_size,
                        LogicalSizeOf::new(None, None),
                    ),
                },
            )
            .expect("grid-lanes pre-placement measurement succeeds");

            let input = tree
                .inputs(1)
                .last()
                .expect("measurement input is recorded");
            let expected = stretches.then_some(grid_axis_size);
            assert_eq!(
                match grid_axis {
                    GridAxisKind::Column => input.known().width,
                    GridAxisKind::Row => input.known().height,
                },
                expected,
                "{label} must resolve pre-placement {grid_axis:?} alignment"
            );
        }
    }
}

#[test]
fn ordinary_grid_order_modified_placement_precedes_mixed_phases_and_preserves_source_identity_in_both_scalar_lanes()
 {
    assert_ordinary_grid_order_modified_placement::<f32>();
    assert_ordinary_grid_order_modified_placement::<f64>();
}

fn assert_ordinary_grid_order_modified_placement<S: LayoutScalar>()
where
    OracleTreeOf<S>: Compute + Traverse<Node = u32, Scalar = S>,
{
    for auto_flow in [
        GridAutoFlow::Row,
        GridAutoFlow::RowDense,
        GridAutoFlow::Column,
        GridAutoFlow::ColumnDense,
    ] {
        let column_flow = auto_flow.is_column();
        let item_style = |order| NodeInputOf::<S> {
            item_order: ItemOrder::new(order),
            size: Size::splat_clone(PreferredSizeOf::px(S::from_f64(10.0))),
            ..NodeInputOf::default()
        };
        let definite_major = |order| NodeInputOf::<S> {
            grid_column: if column_flow {
                GridPlacement::try_line(1).expect("one is a valid grid line")
            } else {
                GridPlacement::AUTO
            },
            grid_row: if column_flow {
                GridPlacement::AUTO
            } else {
                GridPlacement::try_line(1).expect("one is a valid grid line")
            },
            ..item_style(order)
        };
        let mut tree = OracleTreeOf::<S>::new()
            .children(0, [1, 2, 3, 4, 5, 6, 7, 8])
            .children(1, [])
            .children(2, [])
            .children(3, [])
            .children(4, [])
            .children(5, [])
            .children(6, [])
            .children(7, [])
            .children(8, [])
            .style(
                0,
                NodeInputOf {
                    display: Display::Grid,
                    size: Size::splat_clone(PreferredSizeOf::px(S::from_f64(80.0))),
                    grid_template_columns: vec![TrackComponentOf::px(S::from_f64(20.0)); 4],
                    grid_template_rows: vec![TrackComponentOf::px(S::from_f64(20.0)); 4],
                    grid_auto_flow: auto_flow,
                    ..NodeInputOf::default()
                },
            )
            .style(1, item_style(2))
            .style(
                2,
                NodeInputOf {
                    display: Display::None,
                    item_order: ItemOrder::new(i32::MIN),
                    ..item_style(0)
                },
            )
            .style(
                3,
                NodeInputOf {
                    grid_column: GridPlacement::try_line(2).expect("two is a valid grid line"),
                    grid_row: GridPlacement::try_line(2).expect("two is a valid grid line"),
                    item_order: ItemOrder::new(i32::MAX),
                    ..item_style(0)
                },
            )
            .style(4, definite_major(2))
            .style(
                5,
                NodeInputOf {
                    position: Position::Absolute,
                    item_order: ItemOrder::new(i32::MIN),
                    ..item_style(0)
                },
            )
            .style(6, definite_major(-1))
            .style(7, item_style(0))
            .style(8, item_style(2));

        let computation = compute_grid_with_report(
            &mut tree,
            0,
            ComputeInputOf::for_child(
                RunMode::PerformLayout,
                SizingMode::InherentSize,
                RequestedAxis::Both,
                Size::NONE,
                Size::splat(Some(S::from_f64(80.0))),
                ContainingLayoutContext::new(
                    FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
                    ParentFormattingContext::NoParent,
                ),
                Size::splat(AvailableOf::definite(S::from_f64(80.0))),
            ),
        )
        .expect("order-modified ordinary-grid layout succeeds");
        assert!(computation.report().is_empty());

        let expected_cells = if column_flow {
            [
                (6, 0, 0),
                (3, 1, 1),
                (4, 0, 1),
                (7, 0, 2),
                (1, 0, 3),
                (8, 1, 0),
            ]
        } else {
            [
                (6, 0, 0),
                (3, 1, 1),
                (4, 1, 0),
                (7, 2, 0),
                (1, 3, 0),
                (8, 0, 1),
            ]
        };
        for (node, column, row) in expected_cells {
            let layout = tree.layout(node).expect("in-flow child layout is staged");
            assert_eq!(layout.source_index, SourceIndex::new((node - 1) as usize));
            assert_eq!(
                layout.location,
                Point::new(S::from_usize(column * 20), S::from_usize(row * 20)),
                "{auto_flow:?} node {node} must use order-modified placement"
            );
        }
        assert!(
            tree.inputs(2)
                .iter()
                .any(|input| input.run_mode() == RunMode::PerformHiddenLayout),
            "hidden children remain outside the ordinary-grid permutation"
        );
        assert_eq!(
            tree.layout(5)
                .expect("absolute child layout is staged")
                .source_index,
            SourceIndex::new(4)
        );
    }
}

#[test]
fn ordinary_grid_replaced_normal_alignment_starts_while_explicit_stretch_remains_in_both_scalar_lanes()
 {
    assert_ordinary_grid_replaced_normal_alignment::<f32>();
    assert_ordinary_grid_replaced_normal_alignment::<f64>();
}

fn assert_ordinary_grid_replaced_normal_alignment<S: LayoutScalar>()
where
    OracleTreeOf<S>: Compute + Traverse<Node = u32, Scalar = S>,
{
    let measured =
        ComputeOutputOf::from_outer_size(Size::new(S::from_f64(30.0), S::from_f64(20.0)));
    for (label, replaced, item_alignment, container_alignment, expected_known) in [
        ("replaced normal", true, None, None, Size::NONE),
        (
            "non-replaced normal",
            false,
            None,
            None,
            Size::new(Some(S::from_f64(100.0)), Some(S::from_f64(80.0))),
        ),
        (
            "explicit item stretch",
            true,
            Some(AlignItems::Stretch),
            None,
            Size::new(Some(S::from_f64(100.0)), Some(S::from_f64(80.0))),
        ),
        (
            "explicit container stretch",
            true,
            None,
            Some(AlignItems::Stretch),
            Size::new(Some(S::from_f64(100.0)), Some(S::from_f64(80.0))),
        ),
    ] {
        let mut tree = OracleTreeOf::<S>::new()
            .children(0, [1])
            .children(1, [])
            .style(
                0,
                NodeInputOf {
                    display: Display::Grid,
                    size: Size::new(
                        PreferredSizeOf::px(S::from_f64(100.0)),
                        PreferredSizeOf::px(S::from_f64(80.0)),
                    ),
                    grid_template_columns: vec![TrackComponentOf::px(S::from_f64(100.0))],
                    grid_template_rows: vec![TrackComponentOf::px(S::from_f64(80.0))],
                    justify_items: container_alignment,
                    align_items: container_alignment,
                    ..NodeInputOf::default()
                },
            )
            .style(
                1,
                NodeInputOf {
                    item_is_replaced: replaced,
                    justify_self: item_alignment,
                    align_self: item_alignment,
                    ..NodeInputOf::default()
                },
            )
            .measure(1, measured);

        compute_grid(
            &mut tree,
            0,
            ComputeInputOf::for_child(
                RunMode::PerformLayout,
                SizingMode::InherentSize,
                RequestedAxis::Both,
                Size::NONE,
                Size::new(Some(S::from_f64(100.0)), Some(S::from_f64(80.0))),
                ContainingLayoutContext::new(
                    FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
                    ParentFormattingContext::NoParent,
                ),
                Size::new(
                    AvailableOf::definite(S::from_f64(100.0)),
                    AvailableOf::definite(S::from_f64(80.0)),
                ),
            ),
        )
        .expect("replaced ordinary-grid alignment succeeds");

        let layout = tree.layout(1).expect("grid child layout is staged");
        assert_eq!(layout.location, Point::ZERO, "{label} starts in its area");
        assert_eq!(layout.size, measured.size, "{label} keeps measured output");
        let layout_input = tree
            .inputs(1)
            .iter()
            .find(|input| input.run_mode() == RunMode::PerformLayout)
            .expect("grid child receives a perform-layout request");
        assert_eq!(
            layout_input.known(),
            expected_known,
            "{label} resolves normal alignment on both axes"
        );
    }
}

#[test]
fn grid_and_lanes_child_context_is_complete_for_layout_sizing_and_absolute_paths() {
    assert_grid_child_context_is_complete::<f32>();
    assert_grid_child_context_is_complete::<f64>();
}

fn assert_grid_child_context_is_complete<S: LayoutScalar>()
where
    OracleTreeOf<S>: Compute + Traverse<Node = u32, Scalar = S>,
{
    let flow_axes = FlowAxes::new(WritingMode::SidewaysRl, Direction::Rtl);
    let expected =
        crate::ContainingLayoutContext::new(flow_axes, crate::ParentFormattingContext::Grid);

    for display in [Display::Grid, Display::GridLanes] {
        for run_mode in [RunMode::ComputeSize, RunMode::PerformLayout] {
            let mut tree = OracleTreeOf::<S>::new()
                .children(0, [1, 2])
                .children(1, [])
                .children(2, [])
                .style(
                    0,
                    NodeInputOf {
                        display,
                        writing_mode: WritingMode::SidewaysRl,
                        direction: Direction::Rtl,
                        size: Size::new(PreferredSizeOf::AUTO, PreferredSizeOf::AUTO),
                        grid_template_columns: vec![TrackComponentOf::px(S::from_f64(160.0))],
                        grid_template_rows: vec![TrackComponentOf::px(S::from_f64(120.0))],
                        ..NodeInputOf::default()
                    },
                )
                .style(1, NodeInputOf::default())
                .style(
                    2,
                    NodeInputOf {
                        position: Position::Absolute,
                        size: Size::new(
                            PreferredSizeOf::px(S::from_f64(30.0)),
                            PreferredSizeOf::px(S::from_f64(12.0)),
                        ),
                        ..NodeInputOf::default()
                    },
                )
                .measure(
                    1,
                    ComputeOutputOf::from_outer_size(Size::new(
                        S::from_f64(40.0),
                        S::from_f64(20.0),
                    )),
                )
                .measure(
                    2,
                    ComputeOutputOf::from_outer_size(Size::new(
                        S::from_f64(30.0),
                        S::from_f64(12.0),
                    )),
                );

            crate::compute_grid(
                &mut tree,
                0,
                ComputeInputOf::for_child(
                    run_mode,
                    SizingMode::InherentSize,
                    RequestedAxis::Both,
                    Size::NONE,
                    Size::new(Some(S::from_f64(300.0)), Some(S::from_f64(240.0))),
                    crate::ContainingLayoutContext::new(
                        FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
                        crate::ParentFormattingContext::NoParent,
                    ),
                    Size::splat(AvailableOf::definite(S::from_f64(300.0))),
                ),
            )
            .expect("grid context capture layout succeeds");

            let normal_inputs = tree.inputs(1);
            assert!(
                !normal_inputs.is_empty(),
                "{display:?} must request its in-flow child"
            );
            assert!(
                normal_inputs
                    .iter()
                    .all(|input| input.containing_layout_context() == expected),
                "every {display:?} in-flow request must use the parent axes and Grid role: {normal_inputs:#?}"
            );

            if run_mode == RunMode::ComputeSize {
                assert!(
                    normal_inputs
                        .iter()
                        .any(|input| input.run_mode() == RunMode::ComputeSize),
                    "{display:?} intrinsic sizing must request the child through the complete context"
                );
            } else {
                assert!(
                    normal_inputs
                        .iter()
                        .any(|input| input.run_mode() == RunMode::PerformLayout),
                    "{display:?} normal layout must request the child through the complete context"
                );
                let absolute_inputs = tree.inputs(2);
                assert!(
                    absolute_inputs
                        .iter()
                        .any(|input| input.run_mode() == RunMode::PerformLayout),
                    "{display:?} absolute scheduling must request the child"
                );
                assert!(
                    absolute_inputs
                        .iter()
                        .all(|input| input.containing_layout_context() == expected),
                    "every {display:?} absolute request must use the parent axes and Grid role: {absolute_inputs:#?}"
                );
            }
        }
    }
}
use lts::oracle::grid::{
    AlignmentSafety, AutoPlacer, ContributionSize, DefiniteTracks, Flow,
    GridArea as OracleGridArea, GridTrack, ItemContributionFacts, LinePlacement, Track,
    TrackAlignment, TrackSizingSlice, align_tracks_report,
};

fn lp(absolute_px: Scalar, percent_fraction: Scalar) -> LengthPercentageOf {
    LengthPercentageOf::from_coefficients(absolute_px, percent_fraction)
        .expect("test coefficients are finite")
}

fn invalid_numeric_lp() -> LengthPercentageOf {
    LengthPercentageOf::from_coefficients(f32::MAX, f32::MAX).expect("test coefficients are finite")
}

fn fri04_c03_grid_track_value(value: Scalar) -> SizingCalculation {
    SizingCalculation::value(LengthPercentageOf::px(value).expect("test sizing value is finite"))
}

fn fri04_c03_grid_track_nested(
    minimum: Scalar,
    preferred: Scalar,
    maximum: Scalar,
) -> SizingCalculation {
    let preferred = SizingCalculation::max(vec![
        fri04_c03_grid_track_value(preferred),
        SizingCalculation::min(vec![
            fri04_c03_grid_track_value(preferred - 5.0),
            fri04_c03_grid_track_value(preferred + 5.0),
        ])
        .expect("nested minimum is nonempty"),
    ])
    .expect("nested maximum is nonempty");
    SizingCalculation::clamp(
        Some(fri04_c03_grid_track_value(minimum)),
        preferred,
        Some(fri04_c03_grid_track_value(maximum)),
    )
}

fn fri04_c03_grid_track_percentage_nested(
    minimum: Scalar,
    percentage: Scalar,
    maximum: Scalar,
) -> SizingCalculation {
    SizingCalculation::clamp(
        Some(fri04_c03_grid_track_value(minimum)),
        SizingCalculation::max(vec![
            fri04_c03_grid_track_value(minimum - 5.0),
            SizingCalculation::value(
                LengthPercentageOf::from_percent_fraction(percentage)
                    .expect("test percentage is finite"),
            ),
        ])
        .expect("nested maximum is nonempty"),
        Some(fri04_c03_grid_track_value(maximum)),
    )
}

