#[test]
fn fri06_c12_t08_row_and_column_groups_choose_the_lastmost_member() {
    let member = |source, axis, last_baseline| {
        let (child_flow_axes, containing_flow_axes) = match axis {
            GridAxisKind::Column => (
                FlowAxes::new(WritingMode::VerticalRl, Direction::Ltr),
                FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
            ),
            GridAxisKind::Row => (
                FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
                FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
            ),
        };
        ancestor_baseline_member(AncestorBaselineMemberInput {
            source,
            axis,
            ancestor_span: GridTrackSpan::new(1, 2),
            alignment: AlignItems::LastBaseline,
            block_auto_margins: false,
            synthesized_baseline_cycle: false,
            output: ComputeOutput::from_sizes_and_baselines(
                match axis {
                    GridAxisKind::Column => Size::new(50.0, 30.0),
                    GridAxisKind::Row => Size::new(30.0, 50.0),
                },
                match axis {
                    GridAxisKind::Column => Size::new(50.0, 30.0),
                    GridAxisKind::Row => Size::new(30.0, 50.0),
                },
                Baselines {
                    first: Point::NONE,
                    last: match axis {
                        GridAxisKind::Column => Point::new(Some(last_baseline), None),
                        GridAxisKind::Row => Point::new(None, Some(last_baseline)),
                    },
                },
            ),
            margin: Edges::all(0.0),
            child_flow_axes,
            containing_flow_axes,
            start_adjustment: 0.0,
            end_adjustment: 0.0,
        })
        .expect("last-baseline item participates")
    };
    for (axis, physical_axis) in [
        (GridAxisKind::Row, PhysicalAxis::Vertical),
        (GridAxisKind::Column, PhysicalAxis::Horizontal),
    ] {
        let direct = member(1_u32, axis, 25.0);
        let nested = member(2_u32, axis, 10.0);
        let group = AncestorBaselineGroup::reduce(1_u32, axis, physical_axis, 1, [direct, nested]);
        assert_eq!(group.target_for(nested), Some(40.0));
        assert_eq!(group.intrinsic_shim(direct).after, 15.0);
    }
}

fn inherited_placement_member(
    source: u32,
    axis: GridAxisKind,
    role: AncestorBaselineRole,
    selected_track: usize,
    target: f32,
) -> AncestorBaselineMember<u32> {
    let child_flow_axes = match axis {
        GridAxisKind::Column => FlowAxes::new(WritingMode::VerticalLr, Direction::Ltr),
        GridAxisKind::Row => FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
    };
    let physical_baseline = match (axis, role) {
        (GridAxisKind::Column, AncestorBaselineRole::First) => Point::new(Some(target), None),
        (GridAxisKind::Column, AncestorBaselineRole::Last) => {
            Point::new(Some(100.0 - target), None)
        }
        (GridAxisKind::Row, AncestorBaselineRole::First) => Point::new(None, Some(target)),
        (GridAxisKind::Row, AncestorBaselineRole::Last) => Point::new(None, Some(100.0 - target)),
    };
    ancestor_baseline_member(AncestorBaselineMemberInput {
        source,
        axis,
        ancestor_span: GridTrackSpan::new(selected_track + 1, selected_track + 2),
        alignment: match role {
            AncestorBaselineRole::First => AlignItems::Baseline,
            AncestorBaselineRole::Last => AlignItems::LastBaseline,
        },
        block_auto_margins: false,
        synthesized_baseline_cycle: false,
        output: ComputeOutput::from_sizes_and_baselines(
            Size::new(100.0, 100.0),
            Size::new(100.0, 100.0),
            Baselines {
                first: if role == AncestorBaselineRole::First {
                    physical_baseline
                } else {
                    Point::NONE
                },
                last: if role == AncestorBaselineRole::Last {
                    physical_baseline
                } else {
                    Point::NONE
                },
            },
        ),
        margin: Edges::all(0.0),
        child_flow_axes,
        containing_flow_axes: FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
        start_adjustment: 0.0,
        end_adjustment: 0.0,
    })
    .expect("placement fixture member participates")
}

fn inherited_placement_group(
    axis: GridAxisKind,
    role: AncestorBaselineRole,
    selected_track: usize,
    target: f32,
) -> AncestorBaselineGroup<u32> {
    AncestorBaselineGroup::reduce(
        1_u32,
        axis,
        match axis {
            GridAxisKind::Column => PhysicalAxis::Horizontal,
            GridAxisKind::Row => PhysicalAxis::Vertical,
        },
        4,
        [inherited_placement_member(
            91,
            axis,
            role,
            selected_track,
            target,
        )],
    )
}

macro_rules! owner_placement_boundary {
    (
        $parent_grid:expr,
        $current_grid:expr,
        $parent_span:expr,
        $reversed:expr,
        $parent_progression:expr,
        $current_progression:expr,
        $parent_first_frame_origins:expr,
        $parent_last_frame_origins:expr,
        $current_first_frame_origins:expr,
        $current_last_frame_origins:expr,
        $parent_gap:expr,
        $current_gap:expr,
        $start_mbp:expr,
        $end_mbp:expr $(,)?
    ) => {
        OwnerToCurrentPlacementBoundaryInput {
            parent_grid: $parent_grid,
            current_grid: $current_grid,
            parent_axis: GridAxisKind::Row,
            current_axis: GridAxisKind::Row,
            physical_axis: PhysicalAxis::Vertical,
            parent_progression: $parent_progression,
            current_progression: $current_progression,
            parent_span: $parent_span,
            reversed: $reversed,
            parent_first_frame_origins: $parent_first_frame_origins,
            parent_last_frame_origins: $parent_last_frame_origins,
            current_first_frame_origins: $current_first_frame_origins,
            current_last_frame_origins: $current_last_frame_origins,
            parent_boundary_gutters: &vec![
                $parent_gap;
                ($parent_first_frame_origins).len().saturating_sub(1)
            ],
            current_boundary_gutters: &vec![
                $current_gap;
                ($current_first_frame_origins).len().saturating_sub(1)
            ],
            parent_gap: $parent_gap,
            current_gap: $current_gap,
            start_mbp: $start_mbp,
            end_mbp: $end_mbp,
            inherited: true,
        }
    };
}

#[test]
fn owner_to_current_placement_map_identity_has_zero_translation() {
    let map = CheckedOwnerToCurrentPlacementMap::identity(
        1_u32,
        GridAxisKind::Row,
        PhysicalAxis::Vertical,
        PhysicalProgression::Increasing,
        3,
    );

    assert_eq!(map.owner(), 1);
    assert_eq!(map.current_grid(), 1);
    assert_eq!(map.boundary_count(), 0);
    assert_eq!(map.track_count(), 3);
    for local in 0..3 {
        assert_eq!(map.owner_track_for_local(local), Some(local));
        assert_eq!(
            map.translations_for(local, AncestorBaselineRole::First),
            Some((0.0, 0.0)),
        );
        assert_eq!(
            map.translations_for(local, AncestorBaselineRole::Last),
            Some((0.0, 0.0)),
        );
    }
}

#[test]
fn owner_to_current_placement_map_composes_two_boundaries_by_track_and_role() {
    let identity = CheckedOwnerToCurrentPlacementMap::identity(
        1_u32,
        GridAxisKind::Row,
        PhysicalAxis::Vertical,
        PhysicalProgression::Increasing,
        3,
    );
    let first = identity
        .compose(owner_placement_boundary!(
            1,
            2,
            GridTrackSpan::new(0, 3),
            false,
            PhysicalProgression::Increasing,
            PhysicalProgression::Increasing,
            &[0.0, 50.0, 110.0],
            &[40.0, 100.0, 170.0],
            &[0.0, 55.0, 125.0],
            &[40.0, 105.0, 185.0],
            10.0,
            20.0,
            0.0,
            0.0,
        ))
        .unwrap();
    let second = first
        .compose(owner_placement_boundary!(
            2,
            3,
            GridTrackSpan::new(1, 3),
            false,
            PhysicalProgression::Increasing,
            PhysicalProgression::Increasing,
            &[0.0, 55.0, 125.0],
            &[40.0, 105.0, 185.0],
            &[10.0, 90.0],
            &[50.0, 150.0],
            20.0,
            30.0,
            0.0,
            0.0,
        ))
        .unwrap();

    assert_eq!(second.boundary_count(), 2);
    assert_eq!(second.owner_track_for_local(0), Some(1));
    assert_eq!(second.owner_track_for_local(1), Some(2));
    assert_eq!(
        second.translations_for(0, AncestorBaselineRole::First),
        Some((-40.0, 5.0)),
    );
    assert_eq!(
        second.translations_for(1, AncestorBaselineRole::First),
        Some((-20.0, 10.0)),
    );
    assert_eq!(
        second.translations_for(0, AncestorBaselineRole::Last),
        Some((-50.0, -10.0)),
    );
    assert_eq!(
        second.translations_for(1, AncestorBaselineRole::Last),
        Some((-20.0, 0.0)),
    );
}

#[test]
fn owner_to_current_placement_map_composes_reversal_and_physical_progression() {
    let identity = CheckedOwnerToCurrentPlacementMap::identity(
        1_u32,
        GridAxisKind::Row,
        PhysicalAxis::Vertical,
        PhysicalProgression::Increasing,
        3,
    );
    let map = identity
        .compose(owner_placement_boundary!(
            1,
            2,
            GridTrackSpan::new(0, 3),
            true,
            PhysicalProgression::Increasing,
            PhysicalProgression::Decreasing,
            &[0.0, 40.0, 90.0],
            &[30.0, 80.0, 150.0],
            &[5.0, 45.0, 95.0],
            &[35.0, 85.0, 155.0],
            10.0,
            20.0,
            0.0,
            0.0,
        ))
        .unwrap();

    assert_eq!(map.owner_track_for_local(0), Some(2));
    assert_eq!(map.owner_track_for_local(2), Some(0));
    assert_eq!(map.current_progression(), PhysicalProgression::Decreasing);
    assert_eq!(
        map.translations_for(1, AncestorBaselineRole::First),
        Some((5.0, -5.0)),
    );
    assert_eq!(
        map.translations_for(1, AncestorBaselineRole::Last),
        Some((5.0, 5.0)),
    );
}

