fn fri06_c12_t08_nested_inherited_row_baseline_delta(
    parent_gap: f32,
    child_gap: f32,
    reversed: bool,
    alignment: AlignItems,
) -> f32 {
    let child_writing_mode = if reversed {
        WritingMode::VerticalLr
    } else {
        WritingMode::VerticalRl
    };
    let mut tree = OracleTree::new()
        .children(1, [2])
        .children(2, [3, 4])
        .children(3, [])
        .children(4, [5])
        .children(5, [])
        .style(
            1,
            NodeInput {
                display: Display::Grid,
                writing_mode: WritingMode::VerticalRl,
                size: Size::new(PreferredSize::px(140.0), PreferredSize::px(80.0)),
                grid_template_rows: vec![TrackComponent::px(60.0), TrackComponent::px(60.0)],
                grid_template_columns: vec![TrackComponent::px(40.0), TrackComponent::px(40.0)],
                gap: Size::new(Length::px(parent_gap), Length::ZERO),
                ..NodeInput::default()
            },
        )
        .style(
            2,
            NodeInput {
                display: Display::Grid,
                writing_mode: child_writing_mode,
                grid_row: GridPlacement::try_lines(1, 3).expect("valid inherited row span"),
                grid_column: GridPlacement::try_lines(1, 3).expect("valid column span"),
                grid_template_rows: vec![empty_subgrid_track()],
                grid_template_columns: vec![TrackComponent::px(40.0), TrackComponent::px(40.0)],
                gap: Size::new(Length::px(child_gap), Length::ZERO),
                ..NodeInput::default()
            },
        )
        .style(
            3,
            NodeInput {
                writing_mode: child_writing_mode,
                grid_row: GridPlacement::try_line(2).expect("valid direct row"),
                grid_column: GridPlacement::try_line(1).expect("valid direct column"),
                align_self: Some(alignment),
                ..NodeInput::default()
            },
        )
        .style(
            4,
            NodeInput {
                display: Display::Grid,
                writing_mode: child_writing_mode,
                grid_row: GridPlacement::try_lines(1, 3).expect("valid nested row span"),
                grid_column: GridPlacement::try_line(2).expect("valid nested column"),
                grid_template_rows: vec![empty_subgrid_track()],
                grid_template_columns: vec![TrackComponent::px(40.0)],
                gap: Size::new(Length::px(child_gap), Length::ZERO),
                ..NodeInput::default()
            },
        )
        .style(
            5,
            NodeInput {
                writing_mode: child_writing_mode,
                grid_row: GridPlacement::try_line(2).expect("valid flattened row"),
                align_self: Some(alignment),
                ..NodeInput::default()
            },
        );
    let (direct, nested) = match alignment {
        AlignItems::Baseline => (
            vertical_baseline_measure(30.0, 20.0, Some(20.0), None),
            vertical_baseline_measure(30.0, 20.0, Some(5.0), None),
        ),
        AlignItems::LastBaseline => (
            vertical_baseline_measure(30.0, 20.0, None, Some(5.0)),
            vertical_baseline_measure(30.0, 20.0, None, Some(20.0)),
        ),
        _ => unreachable!("the inherited-row control uses baseline alignment"),
    };
    tree = tree.measure(3, direct).measure(5, nested);

    compute_root(
        &mut tree,
        1,
        Size::new(Available::Definite(140.0), Available::Definite(80.0)),
    )
    .expect("nested inherited-row layout computes");
    round_layout(&mut tree, 1).expect("nested inherited-row layout rounds");

    let direct_layout = tree.final_layout(3).expect("direct member is laid out");
    let nested_grid = tree.final_layout(4).expect("nested grid is laid out");
    let nested_layout = tree.final_layout(5).expect("flattened member is laid out");
    let (direct_baseline, nested_baseline) = match alignment {
        AlignItems::Baseline => (20.0, 5.0),
        AlignItems::LastBaseline => (25.0, 10.0),
        _ => unreachable!("the inherited-row control uses baseline alignment"),
    };
    direct_layout.location.x + direct_baseline
        - nested_grid.location.x
        - nested_layout.location.x
        - nested_baseline
}

#[test]
fn fri06_c12_t08_inherited_row_gap_adjustment_stays_in_member_and_view_mapping() {
    let cases = [
        (10.0, 20.0, false, AlignItems::Baseline),
        (10.0, 20.0, false, AlignItems::LastBaseline),
        (20.0, 10.0, false, AlignItems::Baseline),
        (20.0, 10.0, false, AlignItems::LastBaseline),
        (10.0, 20.0, true, AlignItems::Baseline),
        (10.0, 20.0, true, AlignItems::LastBaseline),
        (20.0, 10.0, true, AlignItems::Baseline),
        (20.0, 10.0, true, AlignItems::LastBaseline),
    ];
    let deltas = cases.map(|(parent_gap, child_gap, reversed, alignment)| {
        fri06_c12_t08_nested_inherited_row_baseline_delta(
            parent_gap, child_gap, reversed, alignment,
        )
    });
    assert_eq!(deltas, [0.0; 8]);
}

#[test]
fn fri06_c12_t08_inherited_gap_transform_uses_local_first_and_last_edges_after_reversal() {
    let parent_major = [
        Some(tagged_baseline(PhysicalAxis::Vertical, 14.0)),
        Some(tagged_baseline(PhysicalAxis::Vertical, 30.0)),
    ];
    let parent_minor = [
        Some(tagged_baseline(PhysicalAxis::Vertical, 6.0)),
        Some(tagged_baseline(PhysicalAxis::Vertical, 12.0)),
    ];

    let forward = inherit_subgrid_baselines(SubgridBaselineInheritanceInput {
        parent_major: &parent_major,
        parent_minor: &parent_minor,
        physical_axis: PhysicalAxis::Vertical,
        parent_span: GridTrackSpan::new(1, 3),
        reversed: false,
        start_mbp: 2.0,
        end_mbp: 3.0,
        parent_gap: 10.0,
        subgrid_gap: 20.0,
    })
    .unwrap();
    assert_eq!(
        forward.final_major,
        vec![
            Some(tagged_baseline(PhysicalAxis::Vertical, 12.0)),
            Some(tagged_baseline(PhysicalAxis::Vertical, 25.0)),
        ],
        "first baselines rebase only across their local start edge",
    );
    assert_eq!(
        forward.final_minor,
        vec![
            Some(tagged_baseline(PhysicalAxis::Vertical, 1.0)),
            Some(tagged_baseline(PhysicalAxis::Vertical, 9.0)),
        ],
        "last baselines rebase only across their local end edge",
    );

    let reversed = inherit_subgrid_baselines(SubgridBaselineInheritanceInput {
        parent_major: &parent_major,
        parent_minor: &parent_minor,
        physical_axis: PhysicalAxis::Vertical,
        parent_span: GridTrackSpan::new(1, 3),
        reversed: true,
        start_mbp: 2.0,
        end_mbp: 3.0,
        parent_gap: 10.0,
        subgrid_gap: 20.0,
    })
    .unwrap();
    assert_eq!(
        reversed.final_major,
        vec![
            Some(tagged_baseline(PhysicalAxis::Vertical, 28.0)),
            Some(tagged_baseline(PhysicalAxis::Vertical, 9.0)),
        ],
    );
    assert_eq!(
        reversed.final_minor,
        vec![
            Some(tagged_baseline(PhysicalAxis::Vertical, 7.0)),
            Some(tagged_baseline(PhysicalAxis::Vertical, 3.0)),
        ],
    );
}

fn assert_published_baseline_group_order_keeps_compatible_axis<S: LayoutScalar>(
    incompatible_first: bool,
) where
    lts::layout_tree::OracleTreeOf<S>: Compute + Traverse<Node = u32, Scalar = S>,
{
    let root_children = if incompatible_first { [2, 3] } else { [3, 2] };
    let incompatible_baselines = ComputeOutputOf::from_sizes_and_baselines(
        Size::new(S::from_f64(30.0), S::from_f64(20.0)),
        Size::new(S::from_f64(30.0), S::from_f64(20.0)),
        BaselinesOf {
            first: Point::new(Some(S::from_f64(15.0)), None),
            last: Point::NONE,
        },
    );
    let compatible_baselines = ComputeOutputOf::from_sizes_and_baselines(
        Size::new(S::from_f64(30.0), S::from_f64(20.0)),
        Size::new(S::from_f64(30.0), S::from_f64(20.0)),
        BaselinesOf {
            first: Point::new(None, Some(S::from_f64(14.0))),
            last: Point::NONE,
        },
    );
    let mut tree = lts::layout_tree::OracleTreeOf::<S>::new()
        .children(1, root_children)
        .children(2, [4])
        .children(3, [5])
        .children(4, [])
        .children(5, [])
        .style(
            1,
            NodeInputOf {
                display: Display::Grid,
                size: Size::new(
                    PreferredSizeOf::px(S::from_f64(120.0)),
                    PreferredSizeOf::px(S::from_f64(80.0)),
                ),
                grid_template_columns: vec![
                    TrackComponentOf::px(S::from_f64(60.0)),
                    TrackComponentOf::px(S::from_f64(60.0)),
                ],
                grid_template_rows: vec![TrackComponentOf::px(S::from_f64(80.0))],
                align_items: Some(AlignItems::Start),
                ..NodeInputOf::default()
            },
        )
        .style(
            2,
            NodeInputOf {
                display: Display::Grid,
                writing_mode: WritingMode::VerticalRl,
                grid_row: GridPlacement::try_line(1).expect("first grid row"),
                grid_template_columns: vec![TrackComponentOf::px(S::from_f64(60.0))],
                grid_template_rows: vec![TrackComponentOf::Subgrid(SubgridTrack {
                    name_components: Vec::new(),
                })],
                ..NodeInputOf::default()
            },
        )
        .style(
            3,
            NodeInputOf {
                display: Display::Grid,
                grid_column: GridPlacement::try_line(2).expect("valid grid line"),
                grid_row: GridPlacement::try_line(1).expect("first grid row"),
                grid_template_columns: vec![TrackComponentOf::px(S::from_f64(60.0))],
                grid_template_rows: vec![TrackComponentOf::Subgrid(SubgridTrack {
                    name_components: Vec::new(),
                })],
                ..NodeInputOf::default()
            },
        )
        .style(
            4,
            NodeInputOf {
                writing_mode: WritingMode::VerticalRl,
                align_self: Some(AlignItems::Baseline),
                ..NodeInputOf::default()
            },
        )
        .style(
            5,
            NodeInputOf {
                align_self: Some(AlignItems::Baseline),
                ..NodeInputOf::default()
            },
        )
        .measure(4, incompatible_baselines)
        .measure(5, compatible_baselines);

    let output = compute_grid(
        &mut tree,
        1,
        ComputeInputOf::for_child(
            RunMode::PerformLayout,
            SizingMode::InherentSize,
            RequestedAxis::Both,
            Size::NONE,
            Size::new(Some(S::from_f64(120.0)), Some(S::from_f64(80.0))),
            crate::ContainingLayoutContext::new(
                crate::geometry::FlowAxes::new(WritingMode::HorizontalTb, Direction::Ltr),
                crate::ParentFormattingContext::NoParent,
            ),
            Size::new(
                AvailableOf::definite(S::from_f64(120.0)),
                AvailableOf::definite(S::from_f64(80.0)),
            ),
        ),
    )
    .expect("sibling subgrid layout succeeds");

    assert_eq!(
        output.first_baselines,
        Point::new(Some(S::from_f64(15.0)), Some(S::from_f64(14.0)))
    );
    assert_eq!(output.last_baselines, Point::new(None, Some(S::ZERO)));
}

#[test]
fn baseline_group_order_rejects_incompatible_published_baselines_for_f32() {
    assert_published_baseline_group_order_keeps_compatible_axis::<f32>(true);
    assert_published_baseline_group_order_keeps_compatible_axis::<f32>(false);
}

#[test]
fn baseline_group_order_rejects_incompatible_published_baselines_for_f64() {
    assert_published_baseline_group_order_keeps_compatible_axis::<f64>(true);
    assert_published_baseline_group_order_keeps_compatible_axis::<f64>(false);
}

#[test]
fn column_subgrid_baseline_alignment_does_not_grow_auto_parent_row_twice() {
    let mut tree = OracleTree::new()
        .children(1, [2])
        .children(2, [3, 4])
        .children(3, [])
        .children(4, [])
        .style(
            1,
            NodeInput {
                display: Display::Grid,
                grid_template_columns: vec![TrackComponent::AUTO, TrackComponent::AUTO],
                grid_template_rows: vec![TrackComponent::AUTO],
                align_items: Some(AlignItems::Baseline),
                ..NodeInput::default()
            },
        )
        .style(
            2,
            NodeInput {
                display: Display::Grid,
                grid_column: GridPlacement::try_lines(1, 3).expect("valid grid lines"),
                grid_template_columns: vec![empty_subgrid_track()],
                align_items: Some(AlignItems::Baseline),
                ..NodeInput::default()
            },
        )
        .style(
            3,
            NodeInput {
                display: Display::Grid,
                align_self: Some(AlignItems::Baseline),
                ..NodeInput::default()
            },
        )
        .style(
            4,
            NodeInput {
                display: Display::Grid,
                align_self: Some(AlignItems::Baseline),
                ..NodeInput::default()
            },
        )
        .measure(3, baseline_measure(15.0, 15.0, Some(12.0), None))
        .measure(4, baseline_measure(30.0, 30.0, Some(24.0), None));

    let output = crate::compute_grid(
        &mut tree,
        1,
        ComputeInput::for_child(
            RunMode::PerformLayout,
            SizingMode::InherentSize,
            RequestedAxis::Both,
            Size::NONE,
            Size::NONE,
            crate::ContainingLayoutContext::new(
                crate::geometry::FlowAxes::new(
                    crate::WritingMode::HorizontalTb,
                    crate::Direction::Ltr,
                ),
                crate::ParentFormattingContext::NoParent,
            ),
            Size::new(Available::MAX_CONTENT, Available::MAX_CONTENT),
        ),
    )
    .unwrap();
    tree.set_unrounded(
        1,
        NodeOutput {
            size: output.size,
            content_size: output.content_size,
            ..NodeOutput::new()
        },
    );
    round_layout(&mut tree, 1).unwrap();

    assert_eq!(output.size, Size::new(45.0, 30.0));
    assert_eq!(final_height(&tree, 2), 30.0);
    assert_eq!(final_y(&tree, 3), 12.0);
    assert_eq!(final_y(&tree, 4), 0.0);
}

#[test]
fn grid_auto_places_children_into_declared_column_tracks() {
    let mut tree = OracleTree::new();
    tree.insert_children(1, vec![2, 3]);
    tree.insert_children(2, vec![]);
    tree.insert_children(3, vec![]);
    tree.insert_style(
        1,
        NodeInput {
            display: Display::Grid,
            size: Size::new(PreferredSize::px(200.0), PreferredSize::px(40.0)),
            grid_template_columns: vec![TrackComponent::px(80.0), TrackComponent::px(120.0)],
            grid_template_rows: vec![TrackComponent::px(40.0)],
            ..NodeInput::default()
        },
    );
    tree.insert_style(2, NodeInput::default());
    tree.insert_style(3, NodeInput::default());

    let output = crate::compute_grid(
        &mut tree,
        1,
        ComputeInput::for_child(
            RunMode::PerformLayout,
            SizingMode::InherentSize,
            RequestedAxis::Both,
            Size::NONE,
            Size::new(Some(300.0), Some(200.0)),
            crate::ContainingLayoutContext::new(
                crate::geometry::FlowAxes::new(
                    crate::WritingMode::HorizontalTb,
                    crate::Direction::Ltr,
                ),
                crate::ParentFormattingContext::NoParent,
            ),
            Size::new(Available::MAX_CONTENT, Available::MAX_CONTENT),
        ),
    )
    .unwrap();

    assert_eq!(output.size, Size::new(200.0, 40.0));
    assert_eq!(
        tree.layout(2).expect("node layout is staged").location,
        Point::new(0.0, 0.0)
    );
    assert_eq!(
        tree.layout(2).expect("node layout is staged").size,
        Size::new(80.0, 40.0)
    );
    assert_eq!(
        tree.layout(3).expect("node layout is staged").location,
        Point::new(80.0, 0.0)
    );
    assert_eq!(
        tree.layout(3).expect("node layout is staged").size,
        Size::new(120.0, 40.0)
    );
}

